BEGIN READ ONLY; SET LOCAL search_path=public,extensions;
SELECT jsonb_build_object(
'relation_acl',(SELECT jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',ARRAY(SELECT v::text FROM unnest(c.relacl) v ORDER BY v::text))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private','credentialing') AND c.relkind IN ('r','p','v','m','S','f')),
'function_components',(SELECT jsonb_agg(jsonb_build_object('identity',format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'owner',pg_get_userbyid(p.proowner),'acl',ARRAY(SELECT v::text FROM unnest(p.proacl) v ORDER BY v::text),'definition_md5',md5(pg_get_functiondef(p.oid)),'config',p.proconfig,'definer',p.prosecdef)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private','credentialing') AND p.prokind IN ('f','p')),
'normalized_columns',(SELECT jsonb_agg(jsonb_build_object('identity',identity,'fingerprint',md5(value::text))) FROM (SELECT format('%I.%I.%I',n.nspname,c.relname,a.attname) identity,jsonb_build_array(row_number() OVER(PARTITION BY c.oid ORDER BY a.attnum),format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl,CASE WHEN a.attcollation<>0 THEN a.attcollation::regcollation::text END,pg_get_expr(d.adbin,d.adrelid)) value FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname IN ('public','private','credentialing') AND a.attnum>0 AND NOT a.attisdropped AND c.relkind IN ('r','p','v','m','f')) x),
'view_components',(SELECT jsonb_agg(jsonb_build_object('identity',format('%I.%I',n.nspname,c.relname),'definition_md5',md5(pg_get_viewdef(c.oid,true)),'options',c.reloptions,'owner',pg_get_userbyid(c.relowner))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private','credentialing') AND c.relkind IN ('v','m')),
'counts',(SELECT jsonb_build_object('tables',count(*) FILTER(WHERE c.relkind IN ('r','p')),'rls_tables',count(*) FILTER(WHERE c.relkind IN ('r','p') AND c.relrowsecurity),'views',count(*) FILTER(WHERE c.relkind IN ('v','m'))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private','credentialing')),
'cron',(SELECT jsonb_build_object('total',count(*),'active',count(*) FILTER(WHERE active)) FROM cron.job)
) observation; COMMIT;
